// Tesco category API (GraphQL) response, generated by `npm run types:api` from research/fixtures/ice-cream-api.json.
// The extension reads the DOM, not this API; trailing comments map fields to what the tile shows.

export interface TescoCategoryResponse {
    data:   Data;
    status: number;
}

export interface Data {
    category: Category;
}

export interface Category {
    pageInformation: PageInformation;
    results:         Result[];
    facetLists:      null;
    facets:          Facet[];
    options:         Options;
    __typename:      string;
}

export interface Facet {
    __typename:        string;
    id:                string;
    name:              string;
    type:              string;
    booleanValues?:    BooleanValues;
    multiLevelValues?: MultiLevelValues;
    multiplicity?:     null | string;
    metadata?:         Metadata | null;
    listValues?:       BooleanValues[];
}

export interface BooleanValues {
    count:      number;
    isSelected: null;
    value:      string;
    name:       null | string;
    __typename: string;
}

export interface Metadata {
    description: string; // e.g. "£1.00 Save 1/3 Clubcard Price"
    footerText:  string;
    linkText:    string;
    linkUrl:     string;
    __typename:  string;
}

export interface MultiLevelValues {
    children:      BooleanValues[];
    appliedValues: null;
    __typename:    string;
}

export interface Options {
    sortBy:     string[];
    __typename: string;
}

export interface PageInformation {
    totalCount: number;
    pageNo:     number;
    pageId:     null;
    count:      number;
    pageSize:   number;
    matchType:  null;
    offset:     number;
    query:      Query;
    __typename: string;
}

export interface Query {
    searchTerm: null;
    actualTerm: null;
    queryPhase: string;
    __typename: string;
}

export interface Result {
    node:       Node;
    __typename: string;
}

export interface Node {
    __typename:            string;
    id:                    string;
    tpnb:                  string;
    adId:                  null;
    isForSale:             boolean;
    defaultImageUrl:       string;
    bulkBuyLimitGroupId:   null;
    tpnc:                  string;
    gtin:                  string;
    modelMetadata:         null;
    seller:                null;
    isNew:                 boolean; // DOM: .online-components-product-tile-new-sash__tag ("New")
    fulfilment:            null;
    promotions:            Promotion[]; // DOM: Clubcard value bar (ddsweb-value-bar__*)
    isInFavourites:        null;
    isInAnyList:           null;
    title:                 string; // DOM: product-heading__heading; sizes only exist here (see parsePackSize)
    media:                 Media;
    aisleName:             string;
    departmentName:        string;
    superDepartmentName:   string;
    shelfName:             string;
    details:               Details; // DOM: Aldi Price Match / Low Everyday Price tile labels
    bulkBuyLimit:          number; // JSON only: max quantity per order
    groupBulkBuyLimit:     number;
    averageWeight:         number; // JSON only: loose / catch-weight items
    productType:           string;
    catchWeightList:       null;
    restrictions:          Restriction[]; // JSON only, e.g. "available ... until 31/12/2026"
    variations:            null;
    status:                string;
    price:                 NodePrice; // DOM: product-tile-price__text + unit-price__subtext
    unavailabilityReasons: null;
    substitutions:         unknown[];
    brandName:             string;
    reviews:               Reviews; // DOM: [data-testid="star-rating"] (aria-label "x out of 5")
}

export interface Details {
    components: Component[];
    __typename: string;
}

export interface Component {
    isLowEverydayPricing?: boolean;
    __typename:            string;
    competitors?:          Competitor[];
}

export interface Competitor {
    id:         string;
    priceMatch: PriceMatch;
    __typename: string;
}

export interface PriceMatch {
    isMatching: boolean;
    __typename: string;
}

export interface Media {
    defaultImage: DefaultImage;
    __typename:   string;
}

export interface DefaultImage {
    url:         string;
    aspectRatio: number;
    __typename:  string;
}

export interface NodePrice {
    actual:        number;
    unitPrice:     number;
    unitOfMeasure: string;
    __typename:    string;
}

export interface Promotion {
    id:              string;
    attributes:      string[];
    promotionType:   null;
    __typename:      string;
    startDate:       string;
    endDate:         string; // DOM: hidden value-bar terms "Offer valid ... until dd/mm/yyyy"
    description:     string; // e.g. "£1.00 Save 1/3 Clubcard Price"
    unitSellingInfo: string; // Clubcard unit price, e.g. "£7.14/kg"
    price:           PromotionPrice; // DOM: product-tile-price__text + unit-price__subtext
    missed:          null;
    warnings:        null;
}

export interface PromotionPrice {
    beforeDiscount: null;
    afterDiscount:  number;
    __typename:     string;
}

export interface Restriction {
    isViolated: boolean;
    type:       string;
    __typename: string;
    message:    string;
}

export interface Reviews {
    stats:      Stats;
    __typename: string;
}

export interface Stats {
    noOfReviews:        number;
    overallRating:      number;
    overallRatingRange: number;
    __typename:         string;
}
